import {readFile,writeFile} from 'node:fs/promises';
const root='output/timeouts-concorrencia-26-20261116';
const ler=async p=>JSON.parse(await readFile(root+'/'+p,'utf8'));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('pt-BR',{minimumFractionDigits:3,maximumFractionDigits:3});
const percentil=(a,p)=>{const s=a.slice().sort((a,b)=>a-b);return s[Math.max(0,Math.ceil(s.length*p)-1)]||0};
const estat=a=>({n:a.length,p50:percentil(a,.5),p95:percentil(a,.95),max:Math.max(0,...a)});
const tabela=(cab,linhas)=>'<div class="table"><table><thead><tr>'+cab.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+linhas.map(l=>'<tr>'+l.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
const cargas=[];for(const arquivo of ['antes-api-26.json','depois-api-4.json','depois-api-13.json','depois-api-26.json']){const d=await ler(arquivo);cargas.push({arquivo,...d,estat:estat(d.medidas.map(x=>x.segundos))})}
const leituras=[];for(const n of [4,13,26]){const d=await ler('antes-'+n+'/resultado.json');leituras.push({arquivo:'antes-'+n+'/resultado.json',...d,telas:estat(d.resultados.map(x=>x.segundos)),api:estat(d.requisicoes.map(x=>x.segundos))})}
const pg=await ler('validacao-consultas-pg17.json');const ui=await ler('validacao-documentos-4/resultado.json');
let regressao={resultados:[]};try{regressao=await ler('regressao/resultado.json')}catch{}
const perfis=[...new Set(cargas[1].medidas.map(x=>x.perfil))].sort();
const porPerfil=perfis.map(perfil=>{const r={perfil};for(const d of cargas){const m=d.medidas.filter(x=>x.perfil===perfil);r[d.arquivo]={...estat(m.map(x=>x.segundos)),falhas:d.falhas.filter(x=>x.perfil===perfil).length}}return r});
const resumo={geradoEm:new Date().toISOString(),situacao:'Pendente: carga simultânea não aprovada. Atualização Nano para Micro aguarda autorização para reinício.',migracao:'20261116201751',cargas:cargas.map(d=>({arquivo:d.arquivo,limite:d.limite,pico:d.pico,...d.estat,falhas:d.falhas.length,inicio:d.inicio,fim:d.fim})),porPerfil,ui:{documentos:ui.docs.length,conferidos:ui.docs.filter(d=>d.conferido).length,falhas:ui.falhas.length,etapas:ui.resultados.length},regressao};
await writeFile(root+'/resumo.json',JSON.stringify(resumo,null,2));
await writeFile(root+'/tempos-por-subsistema.csv','subsistema;cenario;chamadas;p50_seg;p95_seg;max_seg;falhas\n'+porPerfil.flatMap(p=>cargas.map(c=>{const e=p[c.arquivo];return[p.perfil,c.arquivo,e.n,num(e.p50),num(e.p95),num(e.max),e.falhas].join(';')})).join('\n'));
const css=`*{box-sizing:border-box}body{margin:0;background:#edf2f1;color:#182e29;font:16px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;background:white;padding:48px}h1{font-size:36px;line-height:1.2;max-width:850px}h2{margin:44px 0 12px;font-size:24px}h3{font-size:18px;margin:24px 0 10px}p{max-width:1000px}.eyebrow{color:#52756d;font-size:13px;text-transform:uppercase;letter-spacing:2px}.alert{padding:22px;background:#fff3db;border-left:5px solid #ad6813;border-radius:6px}.good{padding:18px;background:#edf6f2;border-left:5px solid #328366}.table{overflow:auto;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;background:#1c453b;color:white;padding:12px}td{padding:10px 12px;border-bottom:1px solid #d6e2de;vertical-align:top}tr:nth-child(even){background:#f2f6f4}code{overflow-wrap:anywhere;font-size:12px}a{color:#126347}img{max-width:100%;border:1px solid #d7e1dd;border-radius:8px}small{color:#53665f}.cards{display:flex;gap:12px;flex-wrap:wrap}.card{padding:18px;background:#f1f6f4;flex:1;min-width:180px}.card strong{display:block;font-size:28px}li{margin:8px 0}footer{border-top:1px solid #ccc;margin-top:40px;padding-top:16px;font-size:13px}@media(max-width:600px){main{padding:22px}h1{font-size:28px}}@media print{body{background:white}main{padding:0}h2,h3{break-after:avoid}tr,img,.alert,.good{break-inside:avoid}table{font-size:10px}.table{overflow:visible}a{color:inherit}}`;
const html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Timeouts e concorrência - 26 subsistemas</title><style>${css}</style><main>
<div class="eyebrow">Pátio · investigação em produção · 16/11/2026</div><h1>Timeouts reproduzidos. Correção de consultas aplicada. Concorrência ainda pendente.</h1>
<div class="alert"><b>Esta entrega não está liberada como concluída.</b> A migração autorizada está no Supabase. A carga de 26 usuários continuou falhando; com 13 também houve falhas. O próximo teste depende de aumentar a memória do banco de Nano para Micro, sem acréscimo informado pelo painel. A alteração foi bloqueada pela revisão automática por exigir autorização explícita para o reinício breve de produção.</div>
<p>As falhas originais foram reproduzidas e mantidas neste relatório. Retestes aprovados não apagam os timeouts. Foram usadas somente as 26 empresas fictícias <b>ZZ [TESTE 20261019]</b>. Não houve envio de mensagens nem lançamento de pagamentos.</p>
<div class="cards"><div class="card"><strong>26</strong>subsistemas nas cargas autenticadas</div><div class="card"><strong>130</strong>verificações locais específicas</div><div class="card"><strong>6</strong>funções de consulta otimizadas</div><div class="card"><strong>1 GB</strong>Micro proposto, ainda não aplicado</div></div>
<h2>1. O que foi identificado e corrigido</h2>
<p>O banco publicado usa PostgreSQL 17.6. Funções SQL não incorporadas à consulta externa repetiam a preparação dos planos. Seis funções passaram a PL/pgSQL, reaproveitando o plano entre chamadas no mesmo processo do banco. Os valores, a assinatura, o MFA e as permissões continuam sendo conferidos a cada chamada.</p>
${tabela(['Função','Responsabilidade'],[['private.has_feature','Verificar recursos do plano'],['private.segundo_fator_ok','Validar o segundo fator'],['private.acesso_area','Conferir permissão do módulo'],['public.consultar_meu_acesso','Carregar empresas e recursos do usuário'],['private.candidatos_retorno','Identificar clientes para contato'],['private.detalhes_atendimento_json','Montar os detalhes de assistência, manutenção e limpeza']])}
<p>A migração <code>20261116201751_reduzir_planejamento_consultas_concorrentes.sql</code> foi aplicada após sua autorização. A consulta ao catálogo de produção confirmou as seis funções em PL/pgSQL, mantendo volatilidade, contexto de segurança, <code>search_path</code> e permissões de execução. Não aumentei os limites de espera nem acrescentei retentativas para esconder falhas.</p>
<h3>Comparação controlada em PostgreSQL 17 local</h3>
${tabela(['Versão','Chamadas','Total (s)','P95 por consulta (s)'],pg.tempos.map(t=>[t.versao,t.operacoes,num(t.totalMs/1000),num(t.p95Ms/1000)]))}
<p><small>Teste alternado antes/depois/antes/depois. Resultado local isolado, não uma promessa de velocidade da produção. As 130 verificações comparam retorno completo e testam isolamento entre empresas, expiração de plano e MFA nos 26 perfis.</small></p>
<h2>2. Resultado real com usuários simultâneos</h2>
<p>Cada usuário autenticado consultou sua OS de teste com 12 itens, alterou o desconto, salvou, consultou novamente e verificou o total; depois carregou as notificações. Foram planejadas três rodadas. As cargas que atingiram o limite preventivo de falhas foram interrompidas, sem insistir no servidor.</p>
${tabela(['Cenário (Nano)','Concorrência','Chamadas','Falhas','P50 (s)','P95 (s)','Máximo (s)'],cargas.map(c=>[c.fase==='antes'?'Antes da correção':'Após a correção',c.pico,c.estat.n,c.falhas.length,num(c.estat.p50),num(c.estat.p95),num(c.estat.max)]))}
<p><b>P95</b>: 95% das chamadas observadas terminaram em até esse tempo; inclui respostas com erro. Cada duração vai do envio da chamada à resposta/erro no cliente, incluindo rede e fila. Timeout HTTP de 30 segundos no gerador, distinto do limite de execução SQL. Os erros <code>57014</code> foram confirmados também nos logs PostgreSQL.</p>
<div class="alert">As 312 chamadas aprovadas com quatro usuários são um resultado daquela rodada de API. Não comprovam estabilidade geral com quatro usuários: a rodada de navegador posterior também encontrou três timeouts nas notificações. Os testes precisam ser repetidos após a mudança de capacidade.</div>
<h2>3. Memória e capacidade do servidor</h2>
<p>O painel autenticado confirmou <b>plano Pro com compute Nano</b>. As métricas expuseram aproximadamente <b>406,5 MiB de memória física</b>. Após a rodada de interface, havia cerca de <b>629 MiB em swap</b> e carga de CPU de 3,22 (métrica load1, não porcentagem). Houve tráfego intenso de troca de páginas de memória durante as cargas.</p>
<p>Esse conjunto aponta um gargalo de memória/capacidade além do custo das consultas. A causalidade e o ganho com a mudança precisam ser validados repetindo a mesma carga em Micro; não é correto afirmar que a atualização já resolveu o problema.</p>
<img src="upgrade-sem-acrescimo.png" alt="Supabase: mudança de Nano para Micro, mesmo custo de 9,68 dólares por mês, com reinício automático"><p><small>Preço específico exibido para o projeto: US$ 9,68/mês antes e depois; acréscimo US$ 0,00. Não é o preço total da assinatura Pro. Nenhuma alteração de infraestrutura foi confirmada.</small></p>
<h2>4. Interface publicada e celular</h2>
<p>O frontend testado foi <a href="https://patio-gestao-peach.vercel.app">o site publicado</a>, build <code>${esc(ui.build)}</code>, em Chrome isolado, com telas de 1920 × 1080 e 390 × 844. A migração é de banco, sem mudança de frontend nesta etapa.</p>
<h3>Navegação sem gravar (antes da migração)</h3>
${tabela(['Navegadores','Aberturas de telas','Falhas','P95 tela pronta (s)','P95 chamada API (s)','Máximo API (s)'],leituras.map(d=>[d.limite,d.resultados.length,d.falhas.length,num(d.telas.p95),num(d.api.p95),num(d.api.max)]))}
<p><small>Tela pronta e chamada de API são medidas diferentes. Com 26 navegadores, o computador que gera o teste também influencia a duração da interface. Não atribuir todo o tempo de navegador ao banco.</small></p>
<h3>Criação, edição e consulta com 12 itens</h3>
<p>A rodada após a migração confirmou ${ui.docs.filter(d=>d.conferido).length} documentos criados e editados, com total inicial de R$ 1.080,00 (10% de desconto) e total editado de R$ 1.040,00 (primeiro item com duas unidades e 20% de desconto). Os documentos foram reabertos e conferidos. A rodada foi interrompida no lote seguinte após ${ui.falhas.length} erros de API, antes de completar os 26 perfis.</p>
${tabela(['Subsistema','Operação','Erro','Tempo (s)'],ui.falhas.map(f=>[f.perfil,f.nome,f.erro,num(f.segundos)]))}
<p>Nos documentos concluídos não houve falha nas verificações de transbordamento horizontal. Isso não equivale à aprovação visual de todas as telas: a matriz completa desktop/celular permanece pendente.</p>
<h2>5. Tempos por subsistema</h2><p>Após a migração, ainda no Nano. P95 das chamadas de API. A coluna de falhas é da carga de 26; ausência de falha individual não aprova a rodada global.</p>
${tabela(['Subsistema','API 4: chamadas','API 4: P95 (s)','API 13: P95 (s)','API 26: P95 (s)','API 26: falhas'],porPerfil.map(p=>[p.perfil,p['depois-api-4.json'].n,num(p['depois-api-4.json'].p95),num(p['depois-api-13.json'].p95),num(p['depois-api-26.json'].p95),p['depois-api-26.json'].falhas]))}
<h3>Ensaios descartados das comparações</h3><p>O piloto de gravação da API enviava campos livres de veículo a perfis que não os aceitam; isso foi corrigido no gerador. Uma rodada anterior da interface verificou 51 documentos, mas teve duas falhas de sincronização do próprio teste ao fechar a janela durante uma atualização. O teste passou a esperar os controles estarem disponíveis. Duas tentativas de 26 navegadores com formulários complexos foram interrompidas por limitação do computador gerador, sem etapas completas para comparação. Esses ensaios não foram contados como aprovação nem como bugs confirmados do produto. As cargas de 26 usuários na API usam autenticação real, sem 26 navegadores competindo pelo computador local.</p>
<h2>6. Regressão e integridade</h2>
<p>${regressao.resultados.filter(r=>r.ok).length} de ${regressao.resultados.length} suítes locais concluídas e aprovadas no momento da geração. Os registros individuais e logs estão anexos na pasta de evidências.</p>
${tabela(['Suíte','Resultado','Tempo local (s)'],regressao.resultados.map(r=>[r.arquivo.replace('supabase/tests/',''),r.ok?'Aprovada':'Falhou',num(r.segundos)]))}
<p>O advisor de segurança continua sinalizando funções SECURITY DEFINER expostas, proteção contra senhas vazadas desativada e tabelas com RLS sem políticas. Esse inventário não foi tratado como auditoria de segurança completa nem alterado para melhorar números de desempenho. As seis funções desta correção mantêm suas regras e ACLs.</p>
<h2>7. Próximo passo para concluir</h2><ol><li>Autorizar o reinício e a atualização gratuita Nano → Micro.</li><li>Confirmar a nova capacidade e o retorno do site.</li><li>Repetir cargas de 4, 13 e 26 usuários, com a mesma massa e gravações, incluindo rodadas sustentadas.</li><li>Completar a criação, edição e consulta de OS e orçamentos nos 26 subsistemas, desktop e celular.</li><li>Investigar qualquer falha restante e emitir o relatório final, mantendo todas as falhas e correções anteriores documentadas.</li></ol>
<h2>Evidências reproduzíveis</h2><ul><li><a href="tempos-por-subsistema.csv">Tempos por subsistema em CSV</a></li><li><a href="resumo.json">Resumo estruturado</a></li>${cargas.map(c=>'<li><a href="'+c.arquivo+'">'+c.arquivo+'</a></li>').join('')}<li><a href="validacao-documentos-4/resultado.json">Rodada de interface e falhas das notificações</a></li><li><a href="validacao-consultas-pg17.json">130 verificações e comparação local em PostgreSQL 17</a></li><li><a href="logs-13-usuarios.json">Logs de timeout na carga de 13 usuários</a></li><li><a href="regressao/resultado.json">Regressão local</a></li></ul>
<p>Referências técnicas: <a href="https://www.postgresql.org/docs/17/plpgsql-implementation.html">cache de planos do PL/pgSQL</a>; <a href="https://www.postgresql.org/message-id/E1u02Tn-002Kp0-0Q@gemulon.postgresql.org">mudança de cache de funções SQL posterior ao PostgreSQL 17</a>; <a href="https://supabase.com/docs/guides/platform/compute-and-disk">compute do Supabase</a>.</p>
<footer>Relatório de progresso verificável. Gerado em ${new Date().toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}. Não declara os 26 subsistemas aprovados sob concorrência.</footer></main></html>`;
